func Test_WhitespaceOnlyBoldWrapperKeepsSeparator(t *testing.T) {
	// A bold wrapper holding only a newline-only span still separates the words on either side
	result, err := htmd.Convert(`<b>Alpha</b><b><span>
</span></b><b>Beta</b>`, nil)
	if err != nil {
		t.Fatalf("call failed: %v", err)
	}
	var content string
	if result.Content != nil {
		content = string(*result.Content)
	}
	if string(content) != `**Alpha** **Beta**
` {
		t.Errorf("equals mismatch: got %v", content)
	}
}

func Test_WhitespaceOnlyCodeSpanKept(t *testing.T) {
	// A code span whose content is a single space survives
	result, err := htmd.Convert(`<p>A<code> </code>B</p>`, nil)
	if err != nil {
		t.Fatalf("call failed: %v", err)
	}
	var content string
	if result.Content != nil {
		content = string(*result.Content)
	}
	if string(content) != "A` `B\n" {
		t.Errorf("equals mismatch: got %v", content)
	}
}
